func Memoize[K comparable, V any](f func(K) V) func(K) V {
    var mu sync.Mutex
    cache := map[K]V{}
    return func(k K) V {
        if v, ok := cache[k]; ok {      // two-value lookup: a stored zero value is a hit
            return v
        }
        v := f(k)                       // compute outside the lock: recursion stays safe
        mu.Lock(); cache[k] = v; mu.Unlock()
        return v
    }
}

