var cache sync.Map

func Report(key Key) *Report {
    if v, ok := cache.Load(key); ok {            // fast path: no allocation, no compute
        return v.(*Report)
    }
    v, _ := cache.LoadOrStore(key, build(key))   // build runs even when another goroutine won
    return v.(*Report)
}

var (
    once  sync.Once
    index *Index
)

func Index() *Index {
    once.Do(func() { index = buildIndex() })   // runs once, even under concurrent calls
    return index
}
